38	```cpp
39	// Standalone correctness test for Eigen SVE PacketXd (double).
40	// Build at VL=256 (host) — the same source must also compile at VL=128/512
41	// (compile-only check on host; run on gem5 for 512).
42	// Each op is compared bitwise against a scalar reference loop.
43	#include <Eigen/Core>
44	#include <cmath>
45	#include <cstdio>
46	#include <cstring>
47	#include <cstdint>
48	
49	using namespace Eigen;
50	using namespace Eigen::internal;
51	
52	static int failures = 0;
53	static void check(bool ok, const char* what) {
54	  if (!ok) { printf("FAIL: %s\n", what); failures++; }
55	  else printf("ok: %s\n", what);
56	}
57	
58	static bool bits_eq(double a, double b) {
59	  // NaN compare: both NaN passes; else bitwise (catches -0.0 vs +0.0)
60	  if (std::isnan(a) && std::isnan(b)) return true;
61	  uint64_t x, y; memcpy(&x, &a, 8); memcpy(&y, &b, 8);
62	  return x == y;
63	}
64	
65	int main() {
66	  const int N = packet_traits<double>::size;
67	  printf("PacketXd: size=%d (VL=%d bits) backend=%s\n",
68	         N, EIGEN_ARM64_SVE_VL, Eigen::SimdInstructionSetsInUse());
69	  check(N == EIGEN_ARM64_SVE_VL / 64, "packet size == VL/64");
70	  check((int)unpacket_traits<PacketXd>::size == N, "unpacket size");
71	
72	  alignas(64) double a[64], b[64], r[64], ref[64];
73	  for (int i = 0; i < 64; i++) { a[i] = -3.0 + i * 0.5; b[i] = 2.0 - i * 0.25; }
74	  // exercise a few exact-power-of-two / negative / denormal-free values
75	
76	  // --- pset1 / pload / pstore round trip
77	  PacketXd v = pset1<PacketXd>(7.5);
78	  pstore<double>(r, v);
79	  for (int i = 0; i < N; i++) check(r[i] == 7.5, "pset1/pstore");
80	
81	  PacketXd va = pload<PacketXd>(a), vb = pload<PacketXd>(b);
82	  pstore<double>(r, va); check(memcmp(r, a, N*8) == 0, "pload/pstore aligned");
83	  PacketXd vu = ploadu<PacketXd>(a + 1); pstoreu<double>(r, vu);
84	  check(memcmp(r, a + 1, N*8) == 0, "ploadu/pstoreu");
85	
86	  // --- arithmetic vs scalar reference
87	  #define OP1_TEST(NAME, EXPR_SCALAR) do { \
88	    pstore<double>(r, NAME(va)); \
89	    for (int i = 0; i < N; i++) ref[i] = EXPR_SCALAR; \
90	    for (int i = 0; i < N; i++) check(bits_eq(r[i], ref[i]), #NAME); \
91	  } while (0)
92	  #define OP2_TEST(NAME, EXPR_SCALAR) do { \
93	    pstore<double>(r, NAME(va, vb)); \
94	    for (int i = 0; i < N; i++) ref[i] = EXPR_SCALAR; \
95	    for (int i = 0; i < N; i++) check(bits_eq(r[i], ref[i]), #NAME); \
96	  } while (0)
97	
98	  OP2_TEST(padd, a[i] + b[i]);
99	  OP2_TEST(psub, a[i] - b[i]);
100	  OP2_TEST(pmul, a[i] * b[i]);
101	  OP2_TEST(pdiv, a[i] / b[i]);
102	  OP2_TEST(pmin, a[i] < b[i] ? a[i] : b[i]);
103	  OP2_TEST(pmax, a[i] > b[i] ? a[i] : b[i]);
104	  OP1_TEST(pnegate, -a[i]);
105	  OP1_TEST(pabs, std::abs(a[i]));
106	  OP1_TEST(pfloor, std::floor(a[i]));
107	  OP1_TEST(pceil, std::ceil(a[i]));
108	
109	  // pmadd: c + a*b
110	  PacketXd vc = pset1<PacketXd>(0.25);
111	  pstore<double>(r, pmadd(va, vb, vc));
112	  for (int i = 0; i < N; i++) check(bits_eq(r[i], 0.25 + a[i]*b[i]), "pmadd");
113	
114	  // --- comparisons: all-lanes-true / all-lanes-false patterns
115	  PacketXd ones = pset1<PacketXd>(1.0), zeros = pzero(ones);
116	  PacketXd eq = pcmp_eq(va, va);
117	  pstore<double>(r, eq);
118	  for (int i = 0; i < N; i++) check(r[i] != 0.0, "pcmp_eq self");
119	  PacketXd ne = pcmp_eq(ones, zeros);
120	  pstore<double>(r, ne);
121	  for (int i = 0; i < N; i++) check(r[i] == 0.0, "pcmp_eq diff");
122	
123	  // --- redux
124	  double s = 0; for (int i = 0; i < N; i++) s += a[i];
125	  check(bits_eq(predux(va), s), "predux");
126	  double mx = a[0]; for (int i = 0; i < N; i++) mx = mx > a[i] ? mx : a[i];
127	  check(bits_eq(predux_max(va), mx), "predux_max");
128	  double mn = a[0]; for (int i = 0; i < N; i++) mn = mn < a[i] ? mn : a[i];
129	  check(bits_eq(predux_min(va), mn), "predux_min");
130	
131	  // --- pfirst / preverse / ploaddup
132	  check(pfirst(va) == a[0], "pfirst");
133	  PacketXd rv = preverse(va); pstore<double>(r, rv);
134	  for (int i = 0; i < N; i++) check(r[i] == a[N-1-i], "preverse");
135	  PacketXd dd = ploaddup<PacketXd>(a); pstore<double>(r, dd);
136	  for (int i = 0; i < N/2; i++) { check(r[2*i] == a[i] && r[2*i+1] == a[i], "ploaddup"); }
137	
138	  // --- gather/scatter with stride 3
139	  double g[300]; for (int i = 0; i < 300; i++) g[i] = i * 1.5;
140	  PacketXd pg_ = pgather<double, PacketXd>(g, 3); pstore<double>(r, pg_);
141	  for (int i = 0; i < N; i++) check(r[i] == g[3*i], "pgather");
142	  double sc[300] = {0};
143	  pscatter<double, PacketXd>(sc, va, 2);
144	  for (int i = 0; i < N; i++) check(sc[2*i] == a[i], "pscatter");
145	
146	  // --- plset
147	  PacketXd ls = plset<PacketXd>(10.0); pstore<double>(r, ls);
148	  for (int i = 0; i < N; i++) check(r[i] == 10.0 + i, "plset");
149	
150	  if (failures == 0) { printf("ALL PASS (%d lanes)\n", N); return 0; }
151	  printf("%d FAILURES\n", failures);
152	  return 1;
153	}
154	```
