649	
650	  PacketXi stride_index = svindex_s32(0, N);
651	
652	  for (i = 0; i < N; i++) {
653	    svst1_scatter_s32index_f32(svptrue_b32(), buffer + i, stride_index, kernel.packet[i]);
654	  }
655	
656	  for (i = 0; i < N; i++) {
657	    kernel.packet[i] = svld1_f32(svptrue_b32(), buffer + i * packet_traits<float>::size);
658	  }
659	}
