// Launch a size-specific SVE binary with the task vector length set to argv[1]
// bytes (VL bits = bytes*8). PR_SVE_VL_INHERIT makes it survive exec.
#define _GNU_SOURCE
#include <sys/prctl.h>
#include <unistd.h>
#include <stdio.h>
#include <errno.h>
#ifndef PR_SVE_SET_VL
#define PR_SVE_SET_VL 50
#endif
#ifndef PR_SVE_GET_VL
#define PR_SVE_GET_VL 51
#endif
#ifndef PR_SVE_VL_INHERIT
#define PR_SVE_VL_INHERIT (1 << 17)
#endif
int main(int argc, char **argv) {
  if (argc < 3) { fprintf(stderr, "usage: %s <vl-bytes> <prog> [args...]\n", argv[0]); return 2; }
  long want = atol(argv[1]);
  long rc = prctl(PR_SVE_SET_VL, want | PR_SVE_VL_INHERIT);
  if (rc < 0) { perror("prctl(PR_SVE_SET_VL)"); return 1; }
  printf("task VL set: rc=0x%lx -> %ld bytes (%ld bits), inherit flag\n",
         rc, rc & 0xffff, (rc & 0xffff) * 8);
  fflush(stdout);
  execv(argv[2], &argv[2]);
  perror("execv");
  return 1;
}
EOF
