// Supplemental verification for ops not covered by test_packet_xd.cpp.
// NOT part of the commit — self-verification only.
#include <Eigen/Core>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <cstdint>
using namespace Eigen;
using namespace Eigen::internal;
static int failures = 0;
static void check(bool ok, const char* what) {
  if (!ok) { printf("FAIL: %s\n", what); failures++; } else printf("ok: %s\n", what);
}
static bool bits_eq(double a, double b) {
  if (std::isnan(a) && std::isnan(b)) return true;
  uint64_t x, y; memcpy(&x, &a, 8); memcpy(&y, &b, 8); return x == y;
}
int main() {
  const int N = packet_traits<double>::size;
  printf("N=%d VL=%d\n", N, EIGEN_ARM64_SVE_VL);
  alignas(64) double a[64], b[64], r[64];
  for (int i = 0; i < 64; i++) { a[i] = -3.0 + i * 0.5; b[i] = 2.0 - i * 0.25; }
  PacketXd va = pload<PacketXd>(a), vb = pload<PacketXd>(b);

  // predux_mul
  double m = 1; for (int i = 0; i < N; i++) m *= a[i];
  check(bits_eq(predux_mul(va), m), "predux_mul");

  // ploadquad (requires N >= 4; at VL=128 N=2 the zip pattern still maps a0,a0)
  PacketXd q = ploadquad<PacketXd>(a); pstore<double>(r, q);
  bool qok = true;
  for (int i = 0; i < N; i++) { int src = i / 4; qok = qok && (r[i] == a[src]); }
  check(qok, "ploadquad");

  // bitwise ops via u64 reinterpretation of the double payloads
  PacketXd ones = ptrue(va), zeros = pzero(va);
  pstore<double>(r, ones);
  bool pok = true; for (int i = 0; i < N; i++) { uint64_t u; memcpy(&u, &r[i], 8); pok = pok && (u == ~0ull); }
  check(pok, "ptrue all-ones");
  pstore<double>(r, zeros);
  bool zok = true; for (int i = 0; i < N; i++) { uint64_t u; memcpy(&u, &r[i], 8); zok = zok && (u == 0); }
  check(zok, "pzero all-zeros");
  pstore<double>(r, pand(ones, va));
  bool andok = true; for (int i = 0; i < N; i++) { uint64_t u, v; memcpy(&u, &r[i], 8); memcpy(&v, &a[i], 8); andok = andok && (u == (~0ull & v)); }
  check(andok, "pand");
  pstore<double>(r, por(zeros, va));
  bool orok = true; for (int i = 0; i < N; i++) { uint64_t u, v; memcpy(&u, &r[i], 8); memcpy(&v, &a[i], 8); orok = orok && (u == (0 | v)); }
  check(orok, "por");
  pstore<double>(r, pxor(va, va));
  bool xok = true; for (int i = 0; i < N; i++) xok = xok && (r[i] == 0.0);
  check(xok, "pxor self = 0");
  pstore<double>(r, pandnot(ones, va));
  bool bnok = true; for (int i = 0; i < N; i++) { uint64_t u, v; memcpy(&u, &r[i], 8); memcpy(&v, &a[i], 8); bnok = bnok && (u == (~0ull & ~v)); }
  check(bnok, "pandnot");

  // pconj on real double = identity
  pstore<double>(r, pconj(va));
  check(memcmp(r, a, N*8) == 0, "pconj identity");

  // comparisons: le/lt against reference
  pstore<double>(r, pcmp_le(va, vb));
  bool leok = true; for (int i = 0; i < N; i++) leok = leok && ((r[i] != 0.0) == (a[i] <= b[i]));
  check(leok, "pcmp_le");
  pstore<double>(r, pcmp_lt(va, vb));
  bool ltok = true; for (int i = 0; i < N; i++) ltok = ltok && ((r[i] != 0.0) == (a[i] < b[i]));
  check(ltok, "pcmp_lt");
  // lt_or_nan: a<b or a is nan
  pstore<double>(r, pcmp_lt_or_nan(va, vb));
  bool lnok = true; for (int i = 0; i < N; i++) lnok = lnok && ((r[i] != 0.0) == (a[i] < b[i] || std::isnan(a[i])));
  check(lnok, "pcmp_lt_or_nan");

  // NaN propagation variants: svminnm/svmaxnm return the non-NaN operand
  double na[4] = {1.0, std::nan(""), -2.0, std::nan("")};
  double nb[4] = {std::nan(""), 3.0, std::nan(""), -7.0};
  PacketXd vn = pload<PacketXd>(na), wn = pload<PacketXd>(nb);
  pstore<double>(r, pmin<PropagateNumbers>(vn, wn));
  bool pnok = true; for (int i = 0; i < N; i++) { double want = std::min(na[i % 4], nb[i % 4] == nb[i % 4] ? nb[i % 4] : na[i % 4]); (void)want; }
  // direct: expected elementwise minnum
  double exp_min[4]; for (int i = 0; i < 4; i++) exp_min[i] = std::isnan(na[i]) ? nb[i] : (std::isnan(nb[i]) ? na[i] : (na[i] < nb[i] ? na[i] : nb[i]));
  for (int i = 0; i < N; i++) pnok = pnok && bits_eq(r[i], exp_min[i % 4]);
  check(pnok, "pmin PropagateNumbers (minnum)");
  pstore<double>(r, pmax<PropagateNumbers>(vn, wn));
  double exp_max[4]; for (int i = 0; i < 4; i++) exp_max[i] = std::isnan(na[i]) ? nb[i] : (std::isnan(nb[i]) ? na[i] : (na[i] > nb[i] ? na[i] : nb[i]));
  bool pxok = true; for (int i = 0; i < N; i++) pxok = pxok && bits_eq(r[i], exp_max[i % 4]);
  check(pxok, "pmax PropagateNumbers (maxnum)");
  // plain pmin/pmax with NaN: SVE FMIN returns... (IEEE minNum in older arch returns number; fmin vector returns NaN on modern). Just check PropagateNumbers contract above; plain variant checked in main test.

  // ptranspose 2x2
  double m0[8] = {1, 2, 3, 4, 5, 6, 7, 8};
  double m1[8] = {9, 10, 11, 12, 13, 14, 15, 16};
  PacketBlock<PacketXd, 2> pb2;
  pb2.packet[0] = pload<PacketXd>(m0);
  pb2.packet[1] = pload<PacketXd>(m1);
  ptranspose(pb2);
  pstore<double>(r, pb2.packet[0]);
  bool t0 = (r[0] == 1) && (r[1] == 9);
  for (int i = 2; i < N; i++) t0 = t0 && (r[i] == m0[i] && r[i] == m1[i] ? r[i] == m0[i] : r[i] == m0[i]); // rows beyond 2 stay from m0
  pstore<double>(r, pb2.packet[1]);
  bool t1 = (r[0] == 2) && (r[1] == 10);
  check(t0 && t1, "ptranspose 2x2 head");

  // ptranspose 4x4 at VL=256 (N=4)
  if (N == 4) {
    PacketBlock<PacketXd, 4> pb4;
    for (int i = 0; i < 4; i++) { double tmp[4]; for (int j = 0; j < 4; j++) tmp[j] = i * 10 + j; pb4.packet[i] = pload<PacketXd>(tmp); }
    ptranspose(pb4);
    double rr[4][4];
    for (int i = 0; i < 4; i++) pstore<double>(rr[i], pb4.packet[i]);
    bool ok4 = true;
    for (int i = 0; i < 4; i++) for (int j = 0; j < 4; j++) ok4 = ok4 && (rr[i][j] == j * 10 + i);
    check(ok4, "ptranspose 4x4 full");
  }

  if (failures == 0) { printf("SUPPLEMENTAL ALL PASS (%d lanes)\n", N); return 0; }
  printf("%d SUPPLEMENTAL FAILURES\n", failures);
  return 1;
}
